begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
create function pg_temp.cid(text) returns uuid language sql immutable as $$select md5('trial-credit-test-'||$1)::uuid$$;
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select pg_temp.cid(u),'00000000-0000-0000-0000-000000000000','authenticated','authenticated',u||'@credits.example.test','','{}','{}',now(),now() from unnest(array['owner','viewer','outsider','manager'])u;
insert into organizations(id,name,slug,industry) values(pg_temp.cid('org'),'Credits','trial-credits','salon'),(pg_temp.cid('other'),'Other','trial-credits-other','salon');
insert into organization_memberships(id,organization_id,user_id,role) values
(pg_temp.cid('owner-member'),pg_temp.cid('org'),pg_temp.cid('owner'),'owner'),(pg_temp.cid('viewer-member'),pg_temp.cid('org'),pg_temp.cid('viewer'),'viewer'),(pg_temp.cid('manager-member'),pg_temp.cid('org'),pg_temp.cid('manager'),'manager'),(pg_temp.cid('other-member'),pg_temp.cid('other'),pg_temp.cid('outsider'),'owner');
insert into branches(id,organization_id,name,is_primary) values(pg_temp.cid('main'),pg_temp.cid('org'),'Main',true),(pg_temp.cid('branch2'),pg_temp.cid('org'),'Second',false),(pg_temp.cid('other-branch'),pg_temp.cid('other'),'Other',true);
insert into membership_branch_assignments(organization_id,membership_id,branch_id) values(pg_temp.cid('org'),pg_temp.cid('viewer-member'),pg_temp.cid('main'));
insert into customers(id,organization_id,full_name) select pg_temp.cid('customer-'||n),pg_temp.cid('org'),'Client '||lpad(n::text,3,'0') from generate_series(1,51)n;
insert into appointments(id,organization_id,branch_id,customer_id,starts_at,expected_duration_minutes,status) select pg_temp.cid('visit-'||n),pg_temp.cid('org'),pg_temp.cid('main'),pg_temp.cid('customer-'||n),now(),30,'completed' from generate_series(1,51)n;
create function pg_temp.payload(kind text default 'clients',action text default 'advanced_report',branch uuid default null) returns jsonb language sql as $$select jsonb_build_object('kind',kind,'action',action,'start',current_date-2,'end',current_date+1,'branch',branch)$$;

insert into trial_credit_accounts(organization_id,remaining) values(pg_temp.cid('org'),2);
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.cid('owner'),'role','authenticated')::text,true);
set local role authenticated;
select is((generate_credit_report(pg_temp.cid('org'),pg_temp.cid('first'),pg_temp.payload())->>'cost')::integer,1,'Free filtering costs one credit');
select is((get_credit_usage(pg_temp.cid('org'))->>'remaining')::integer,1,'shared ledger balance decremented');
select is((generate_credit_report(pg_temp.cid('org'),pg_temp.cid('first'),pg_temp.payload())->>'remaining')::integer,1,'retry does not debit twice');
select is((read_credit_report(pg_temp.cid('org'),pg_temp.cid('first'))->>'remaining')::integer,1,'reopen does not debit');
select ok(not has_entitlement(pg_temp.cid('org'),'advanced_reports'),'paid entitlement does not leak outside adapter');
select throws_ok($$select get_client_purchase_report(pg_temp.cid('org'),current_date-2,current_date+1)$$,'42501',null,'unmetered advanced bypass denied');
select throws_ok($$select generate_credit_report(pg_temp.cid('org'),pg_temp.cid('first'),pg_temp.payload('overview'))$$,'22023',null,'changed retry filters rejected');
select throws_ok($$select generate_credit_report(pg_temp.cid('org'),pg_temp.cid('foreign'),pg_temp.payload('clients','advanced_report',pg_temp.cid('other-branch')))$$,'42501',null,'cross tenant branch rejected');
select is((get_credit_usage(pg_temp.cid('org'))->>'remaining')::integer,1,'failed generation rolls reservation back');
select throws_ok($$select generate_credit_report(pg_temp.cid('org'),pg_temp.cid('no-consent'),pg_temp.payload()||'{"maxCost":0}')$$,'P0002',null,'cost ceiling is respected');
select is((generate_credit_report(pg_temp.cid('org'),pg_temp.cid('csv'),pg_temp.payload('clients','csv_export'))->>'cost')::integer,1,'Free CSV preparation costs one credit');
select is((get_credit_usage(pg_temp.cid('org'))->>'remaining')::integer,0,'CSV uses last credit');
select is((generate_credit_report(pg_temp.cid('org'),pg_temp.cid('csv'),pg_temp.payload('clients','csv_export'))->>'remaining')::integer,0,'CSV retry works at zero without another debit');
select is(generate_credit_report(pg_temp.cid('org'),pg_temp.cid('empty'),pg_temp.payload())->>'code','INSUFFICIENT_CREDITS','zero blocks new generation');
select lives_ok($$select read_credit_report(pg_temp.cid('org'),pg_temp.cid('csv'))$$,'saved CSV stays readable at zero');
select ok(jsonb_array_length(get_credit_notices(pg_temp.cid('org')))>0,'owner receives low or empty notice');
reset role;
select is((select count(*) from organization_credit_ledger where organization_id=pg_temp.cid('org') and transaction_type='USAGE'),2::bigint,'exactly two ledger debits');
select is((select count(*) from organization_credit_reservations where organization_id=pg_temp.cid('org') and status='reserved'),0::bigint,'no abandoned reservations');
select is((select count(*) from trial_report_context),0::bigint,'temporary report access cleared');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.cid('outsider'),'role','authenticated')::text,true);
set local role authenticated;
select throws_ok($$select generate_credit_report(pg_temp.cid('org'),pg_temp.cid('outsider-request'),pg_temp.payload())$$,'42501',null,'outsider cannot spend credits');
reset role;
-- Synthetic test-only disabled pricing verifies null costs do not consume credits.
update credit_operation_registry set credit_cost=null where operation_key='advanced_report';
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.cid('owner'),'role','authenticated')::text,true);
set local role authenticated;
select is((generate_credit_report(pg_temp.cid('org'),pg_temp.cid('unconfigured'),pg_temp.payload())->>'cost')::integer,0,'unset operation cost never debits');
reset role;
-- Fixed seven-day defaults are available even when no credits remain.
update appointments set starts_at=now()-interval '8 days' where id=pg_temp.cid('visit-51');
set local role authenticated;
select is((get_recent_client_purchases(pg_temp.cid('org'),pg_temp.cid('main'))->>'count')::integer,50,'recent default excludes older activity');
select is(jsonb_array_length(get_recent_client_purchases(pg_temp.cid('org'),pg_temp.cid('main'))->'rows'),50,'recent rows are available immediately');
select is((get_credit_usage(pg_temp.cid('org'))->>'remaining')::integer,0,'default report does not spend credits');
select ok(not has_entitlement(pg_temp.cid('org'),'advanced_reports'),'recent read does not leak advanced access');
select throws_ok($$select get_recent_client_purchases(pg_temp.cid('org'),pg_temp.cid('other-branch'))$$,'42501',null,'recent defaults reject foreign branch');
select throws_ok($$select get_recent_client_purchases(pg_temp.cid('org'),null)$$,'42501',null,'recent defaults require one branch');
select throws_ok($$select get_recent_client_purchases(pg_temp.cid('org'),pg_temp.cid('main'),'invalid')$$,'22023',null,'invalid category rejected');
reset role;
select is((select count(*) from trial_report_context),0::bigint,'recent context removed after success and failed calls');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.cid('outsider'),'role','authenticated')::text,true);
set local role authenticated;
select throws_ok($$select get_recent_client_purchases(pg_temp.cid('org'),pg_temp.cid('main'))$$,'42501',null,'outsider cannot read recent purchases');
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.cid('viewer'),'role','authenticated')::text,true);
set local role authenticated;
select throws_ok($$select get_recent_client_purchases(pg_temp.cid('org'),pg_temp.cid('branch2'))$$,'42501',null,'unassigned branch remains unavailable');
reset role;
update organizations set financial_report_roles_only=true where id=pg_temp.cid('org');
set local role authenticated;
select throws_ok($$select get_recent_client_purchases(pg_temp.cid('org'),pg_temp.cid('main'))$$,'42501',null,'financial role restriction remains enforced');
reset role;
update credit_operation_registry set credit_cost=1 where operation_key='advanced_report';
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.cid('outsider'),'role','authenticated')::text,true);
set local role authenticated;
select is((generate_credit_report(pg_temp.cid('other'),pg_temp.cid('promo-credit'),pg_temp.payload('catalog')||jsonb_build_object('section','promos','branch',pg_temp.cid('other-branch')))->>'cost')::integer,1,'custom promo report uses approved one-credit charge');
select is((generate_credit_report(pg_temp.cid('other'),pg_temp.cid('promo-credit'),pg_temp.payload('catalog')||jsonb_build_object('section','promos','branch',pg_temp.cid('other-branch')))->>'remaining')::integer,99,'promo retry does not double-charge');
select throws_ok($$select generate_credit_report(pg_temp.cid('other'),pg_temp.cid('invalid-room-credit'),pg_temp.payload('catalog')||jsonb_build_object('section','rooms','branch',pg_temp.cid('other-branch')))$$,'42501',null,'non-hospitality room request rejected');
select is((get_credit_usage(pg_temp.cid('other'))->>'remaining')::integer,99,'rejected room report rolls credit reservation back');
reset role;
select * from finish();
rollback;
